package com.calpex_technologies.chama.entity;

import jakarta.persistence.*;
import lombok.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;

/**
 * Tracks penalties imposed on loans due to late/missed payments.
 * Can be auto-generated by scheduler or manually imposed by admin.
 */
@Entity
@Table(name = "loan_penalties")
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class LoanPenalty {
    
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "tenant_id", nullable = false)
    private Tenant tenant;
    
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "loan_id", nullable = false)
    private Loan loan;
    
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "member_id", nullable = false)
    private Member member;
    
    @Column(nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;
    
    @Column(name = "paid_amount", precision = 15, scale = 2)
    @Builder.Default
    private BigDecimal paidAmount = BigDecimal.ZERO;
    
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    @Builder.Default
    private PenaltyStatus status = PenaltyStatus.UNPAID;
    
    @Column(columnDefinition = "TEXT")
    private String reason; // e.g. "Late payment for June 2026 installment"
    
    @Column(name = "due_date")
    private LocalDate dueDate; // The due date that was missed
    
    @Column(name = "period_number")
    private Integer periodNumber; // Which payment period (1, 2, 3, etc.)
    
    @Column(name = "days_overdue")
    private Integer daysOverdue; // How many days overdue when penalty was applied
    
    @Column(name = "is_auto_generated", nullable = false)
    @Builder.Default
    private boolean autoGenerated = true;
    
    @Column(name = "imposed_at", nullable = false)
    private LocalDateTime imposedAt;
    
    @Column(name = "paid_at")
    private LocalDateTime paidAt;
    
    @Column(name = "waived_at")
    private LocalDateTime waivedAt;
    
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "waived_by_id")
    private Member waivedBy;
    
    @Column(name = "waive_reason", columnDefinition = "TEXT")
    private String waiveReason;
    
    @PrePersist
    protected void onCreate() {
        if (imposedAt == null) {
            imposedAt = LocalDateTime.now();
        }
    }
    
    public BigDecimal getBalance() {
        return amount.subtract(paidAmount != null ? paidAmount : BigDecimal.ZERO);
    }
    
    public enum PenaltyStatus {
        UNPAID,     // Not yet paid
        PARTIAL,    // Partially paid
        PAID,       // Fully paid
        WAIVED      // Waived by admin
    }
}
